mapper.insert:
insert into huli_renyuan (
    yonghu_id, gonghao, xingming, xingbie, shouji, zhicheng, ruzhi_riqi, zhuangtai, beizhu
) values (
    #{yonghuId}, #{gonghao}, #{xingming}, #{xingbie}, #{shouji}, #{zhicheng}, #{ruzhiRiqi}, coalesce(#{zhuangtai}, '在职'), #{beizhu}
)

mapper.select:
select count(1)
from renyuan_laoren
where huli_renyuan_id = #{huliRenyuanId}
  and laoren_id = #{laorenId}
  and zhuangtai = '服务中'

mapper.update:
update renyuan_laoren
set zhuangtai = '已结束',
    jieshu_riqi = curdate()
where huli_renyuan_id = #{huliRenyuanId}
  and laoren_id = #{laorenId}
  and zhuangtai = '服务中'

mapper.insert:
insert into renyuan_laoren (
    huli_renyuan_id, laoren_id, kaishi_riqi, zhuangtai, beizhu
) values (
    #{huliRenyuanId}, #{laorenId}, coalesce(#{kaishiRiqi}, curdate()), '服务中', #{beizhu}
)
